  "tokenized_directions": [
    {
      "step": 1,
      "text": "PUT IN THE MORTAR {{ing_01|PEPPER}}, {{ing_02|LOVAGE}} AND {{ing_03|ORIGANY}}, MOISTEN WITH {{ing_04|BROTH}} AND RUB; ADD {{ing_05|COOKED BRAINS}} AND MIX DILIGENTLY SO THAT THERE BE NO LUMPS."
    },
    {
      "step": 2,
      "text": "INCORPORATE {{ing_06|FIVE EGGS}} AND CONTINUE MIXING WELL TO HAVE A GOOD FORCEMEAT WHICH YOU MAY THIN WITH {{ing_04|BROTH}}."
    },
    {
      "step": 3,
      "text": "SPREAD THIS OUT IN A METAL PAN, COOK, AND WHEN COOKED [cold] UNMOULD IT ONTO A CLEAN TABLE."
    },
    {
      "step": 4,
      "text": "CUT INTO HANDY SIZE."
    },
    {
      "step": 5,
      "text": "[Now prepare a sauce] PUT IN THE MORTAR {{ing_01|PEPPER}}, {{ing_02|LOVAGE}} AND {{ing_03|ORIGANY}}, CRUSH, MIX WITH {{ing_04|BROTH}} PUT INTO A SAUCE PAN, BOIL, THICKEN AND STRAIN."
    },
    {
      "step": 6,
      "text": "HEAT THE PIECES OF BRAIN PUDDING IN THIS SAUCE THOROUGHLY, DISH THEM UP, SPRINKLED WITH {{ing_01|PEPPER}}, IN A MUSHROOM DISH."
    }
